```file wpool/queue.py
"""A bounded work queue."""
import threading


class Full(Exception):
    pass


class Closed(Exception):
    pass


class Queue:
    def __init__(self, maxsize=0):
        self.maxsize = maxsize
        self._items = []
        self._closed = False
        self._unfinished = 0
        self._cond = threading.Condition()

    def get(self, timeout=None):
        with self._cond:
            if self._closed:
                return None
            if not self._cond.wait_for(lambda: self._items or self._closed, timeout):
                return None
            if self._closed:
                return None
            item = self._items.pop(0)
            self._unfinished += 1
            self._cond.notify()
            return item

    def put(self, item, timeout=None):
        with self._cond:
            if self._closed:
                raise Closed()
            if not self._cond.wait_for(
                lambda: self.maxsize == 0 or len(self._items) < self.maxsize,
                timeout,
            ):
                raise Full()
            self._items.append(item)
            self._cond.notify()

    def task_done(self):
        with self._cond:
            self._unfinished -= 1
            self._cond.notify_all()

    def close(self):
        with self._cond:
            self._closed = True
            self._cond.notify_all()

    @property
    def unfinished(self):
        return self._unfinished

    def join(self, timeout=None):
        with self._cond:
            if not self._cond.wait_for(lambda: self._unfinished == 0, timeout):
                raise Full()
