"""HTTP client with retries."""
import time

IDEMPOTENT_METHODS = frozenset({"GET", "HEAD", "PUT", "DELETE"})


class Transient(Exception):
    pass


class Client:
    def __init__(self, transport, backoff=0.01):
        self.transport = transport
        self.backoff = backoff

    def call(self, method, path, body=None, timeout=1.0, attempts=3, idempotency_key=None):
        method_upper = method.upper()
        retryable = (
            method_upper in IDEMPOTENT_METHODS
            or (method_upper == "POST" and idempotency_key is not None)
        )

        headers = {}
        if idempotency_key is not None:
            headers["Idempotency-Key"] = idempotency_key

        last_transient = None
        for i in range(attempts):
            if i:
                time.sleep(self.backoff * 2 ** (i - 1))
            try:
                r = self.transport(method, path, body, headers)
            except Transient as e:
                if not retryable:
                    raise
                last_transient = e
                continue
            return r

        raise last_transient
