"""Event-sourced aggregate."""
import copy


class InvalidEvent(Exception):
    pass


class Aggregate:
    def __init__(self):
        self.state = {'count': 0, 'total': 0}
        self.version = 0
        self.pending = []
        self._applied_seqs = set()

    def apply(self, event):
        name = event.get('name')
        if name != 'added':
            raise InvalidEvent(name)
        seq = event.get('seq')
        if seq is not None and seq in self._applied_seqs:
            raise InvalidEvent(f"duplicate seq {seq}")

        self.state['count'] += 1
        self.state['total'] += event['amount']
        self.version += 1
        if seq is not None:
            self._applied_seqs.add(seq)
        if event in self.pending:
            self.pending.remove(event)

    def handle(self, command):
        events = [{'name': 'added', 'amount': command.get('amount', 0)}]
        self.pending.extend(events)
        return events

    def rehydrate(self, events):
        for event in events:
            self.apply(event)
        return self

    def snapshot(self):
        return copy.deepcopy(self.state)
