"""Deduplicating store."""

import threading
from itertools import islice


class Store:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()
        self._offer_count = {}

    def get(self, key):
        return self._data.get(key)

    def put_if_absent(self, key, value):
        with self._lock:
            self._offer_count[key] = self._offer_count.get(key, 0) + 1
            if key in self._data:
                return False
            self._data[key] = value
            return True

    def process(self, items, chunk=500):
        stored = dupes = 0
        it = iter(items)
        while True:
            batch = list(islice(it, chunk))
            if not batch:
                break
            for k, v in batch:
                if self.put_if_absent(k, v):
                    stored += 1
                else:
                    dupes += 1
        return {'stored': stored, 'duplicates': dupes}

    def stats(self):
        with self._lock:
            keys = len(self._data)
            contended = sum(1 for c in self._offer_count.values() if c > 1)
        return {'keys': keys, 'contended': contended}

    def __len__(self):
        with self._lock:
            return len(self._data)
