"""CSV reading and writing."""
import csv as _csv
import io
import os


DIALECTS = {'excel': ',', 'excel-tab': '\t', 'pipe': '|'}


class Reader:
    def __init__(self, source, dialect='excel', delimiter=None):
        if isinstance(source, str):
            source = io.StringIO(source)
        self.source = source
        self.delimiter = delimiter or DIALECTS.get(dialect, ',')
        self._fieldnames = None
        self._rows = None

    @property
    def fieldnames(self):
        if self._fieldnames is None:
            self._parse()
        return self._fieldnames

    def _parse(self):
        reader = _csv.reader(self.source, delimiter=self.delimiter)
        all_rows = list(reader)
        self._fieldnames = []
        self._rows = []
        header_found = False
        for row in all_rows:
            if all(field.strip() == '' for field in row):
                continue
            if not header_found:
                self._fieldnames = [f.strip() for f in row]
                header_found = True
            else:
                d = {}
                for i, key in enumerate(self._fieldnames):
                    if i < len(row):
                        d[key] = row[i].strip()
                    else:
                        d[key] = None
                self._rows.append(d)

    def rows(self):
        if self._rows is None:
            self._parse()
        return iter(self._rows)

    @classmethod
    def read(cls, path_or_text, dialect='excel', delimiter=None):
        if isinstance(path_or_text, str) and os.path.exists(path_or_text):
            with open(path_or_text, 'r', newline='') as f:
                return cls(f, dialect=dialect, delimiter=delimiter)
        return cls(path_or_text, dialect=dialect, delimiter=delimiter)

    @classmethod
    def write(cls, path, fieldnames, rows, dialect='excel', delimiter=None):
        delim = delimiter or DIALECTS.get(dialect, ',')
        with open(path, 'w', newline='') as f:
            writer = _csv.writer(f, delimiter=delim, quoting=_csv.QUOTE_MINIMAL,
                                 lineterminator='\n')
            writer.writerow(fieldnames)
            for row in rows:
                writer.writerow([row.get(fn) for fn in fieldnames])
