"""Job runner."""


class Runner:
    def __init__(self, max_per_tenant=2):
        self.max_per_tenant = max_per_tenant
        self._q = []
        self._results = []
        self._failed = 0
        self._run_count = 0
        self._last = None
        self._streak = 0
        self._seq = 0

    def submit(self, tenant, fn, *, priority=0):
        self._q.append((tenant, fn, priority, self._seq))
        self._seq += 1

    def run(self, limit=None):
        if limit is None:
            limit = len(self._q)

        results = []
        for _ in range(limit):
            if not self._q:
                break

            eligible = [
                job for job in self._q
                if not (job[0] == self._last and self._streak >= self.max_per_tenant)
            ]

            if not eligible:
                eligible = list(self._q)

            eligible.sort(key=lambda j: (-j[2], j[3]))
            chosen = eligible[0]
            self._q.remove(chosen)

            tenant, fn, priority, seq = chosen
            try:
                result = fn()
                results.append({'ok': True, 'result': result})
            except Exception as e:
                results.append({'ok': False, 'error': str(e)})
                self._failed += 1

            self._run_count += 1

            if tenant == self._last:
                self._streak += 1
            else:
                self._last = tenant
                self._streak = 1

        self._results.extend(results)
        return results

    def pending(self):
        return len(self._q)

    def stats(self):
        return {
            'run': self._run_count,
            'failed': self._failed,
            'skipped': self.pending(),
        }

    def reset(self):
        self._q = []
        self._last = None
        self._streak = 0
