"""Migration runner."""

from .errors import MigrationError


def plan(migrations):
    names = set()
    for m in migrations:
        if m['name'] in names:
            raise MigrationError(f"Duplicate migration name: {m['name']}")
        names.add(m['name'])

    for m in migrations:
        for dep in m['deps']:
            if dep not in names:
                raise MigrationError(f"Missing dependency: {dep}")

    in_degree = {name: 0 for name in names}
    dependents = {name: [] for name in names}

    for m in migrations:
        for dep in m['deps']:
            in_degree[m['name']] += 1
            dependents[dep].append(m['name'])

    available = sorted(name for name in names if in_degree[name] == 0)
    result = []

    while available:
        node = available.pop(0)
        result.append(node)
        for dep in sorted(dependents[node]):
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                available.append(dep)
        available.sort()

    if len(result) != len(names):
        raise MigrationError("Dependency cycle detected")

    return result


def applied(db):
    return set(db.applied_migrations)


def migrate(conn, migrations, db, dry_run=False):
    ordered = plan(migrations)
    already_applied = applied(db)
    to_apply = [name for name in ordered if name not in already_applied]

    if dry_run:
        return to_apply

    by_name = {m['name']: m for m in migrations}
    applied_this_call = []

    try:
        for name in to_apply:
            by_name[name]['up'](conn)
            db.record(name)
            applied_this_call.append(name)
    except Exception:
        for name in reversed(applied_this_call):
            by_name[name]['down'](conn)
            db.applied_migrations.remove(name)
        raise

    return applied_this_call


def rollback_last(conn, migrations, db):
    if not db.applied_migrations:
        return None

    name = db.applied_migrations[-1]
    by_name = {m['name']: m for m in migrations}
    by_name[name]['down'](conn)
    db.applied_migrations.remove(name)
    return name
