class Windowed:
    _peak = 0

    def __init__(self, source, size, fn, key=None):
        if size <= 0:
            raise ValueError("size must be positive")
        self.source = source
        self.size = size
        self.fn = fn
        self.key = key

    def __iter__(self):
        buffers = {}
        for pair in self.source:
            if self.key is None:
                k = None
            else:
                k = self.key(pair)
            value = pair[1]
            if k not in buffers:
                buffers[k] = []
            buffers[k].append(value)
            if len(buffers[k]) > Windowed._peak:
                Windowed._peak = len(buffers[k])
            if len(buffers[k]) == self.size:
                yield (k, self.fn(buffers[k]))
                buffers[k] = []

    @classmethod
    def peak_memory(cls):
        return cls._peak


def summarise(source, size, fn, key=None):
