class Windowed:
    _peak = 0

    def __init__(self, source, size, fn, key=None):
        if size <= 0:
            raise ValueError("size must be positive")
        self.source = source
        self.size = size
        self.fn = fn
        self.key = key

    def __iter__(self):
        buffers = {}
        for pair in self.source:
            if self.key is None:
                k = None
            else:
