"""Bounded queue with backpressure."""

import threading


class Full(Exception):
    pass


class Closed(Exception):
    pass


class BoundedQueue:
    def __init__(self, maxsize=0):
        self.maxsize = maxsize
        self._items = []
        self._closed = False
        self._cond = threading.Condition()

    def put(self, item, timeout=None):
        with self._cond:
            if self._closed:
                return False
            if self.maxsize > 0:
                self._cond.wait_for(
                    lambda: len(self._items) < self.maxsize or self._closed,
                    timeout=timeout,
                )
                if self._closed:
                    return False
                if len(self._items) >= self.maxsize:
                    raise Full()
            self._items.append(item)
            self._cond.notify_all()
            return True

    def get(self, timeout=None):
        with self._cond:
            if self._closed and not self._items:
                return None
            self._cond.wait_for(
                lambda: self._items or self._closed,
                timeout=timeout,
            )
            if not self._items:
                return None
            item = self._items.pop(0)
            self._cond.notify_all()
            return item

    def close(self):
        with self._cond:
            self._closed = True
            self._cond.notify_all()

    def qsize(self):
        with self._cond:
            return len(self._items)

    def __len__(self):
        return self.qsize()

    def drop_oldest(self):
        with self._cond:
            if self._items:
                item = self._items.pop(0)
                self._cond.notify_all()
                return item
            return None
