"""Draining pipeline."""


class DrainError(Exception):
    def __init__(self, message, items=None, cause=None):
        super().__init__(message)
        self.items = list(items or [])
        self.cause = cause


def collect(source, batch_size=100):
    items = []
    try:
        if hasattr(source, "read_batch"):
            while True:
                batch = source.read_batch(batch_size)
                if not batch:
                    break
                items.extend(batch)
        else:
            for item in source:
                items.append(item)
    except Exception as exc:
        raise DrainError(
            f"Source raised during collect: {exc}",
            items=items,
            cause=exc,
        ) from exc
    finally:
        source.close()
    return items


def drain(source):
    try:
        if hasattr(source, "read_batch"):
            while True:
                batch = source.read_batch(1)
                if not batch:
                    break
                for item in batch:
                    yield item
        else:
            for item in source:
                yield item
    finally:
        source.close()


def close_all(sources):
    errors = []
    for source in sources:
        try:
            source.close()
        except Exception as exc:
            errors.append(exc)
    if errors:
        messages = "; ".join(str(e) for e in errors)
        raise DrainError(f"Failed to close sources: {messages}")
