"""Dependency graph."""


class Graph:
    def __init__(self):
        self._mods = {}

    def add_module(self, name, provides=(), requires=()):
        self._mods[name] = (set(provides), set(requires))

    def dependents(self, name):
        result = []
        for mod_name, (provides, requires) in self._mods.items():
            if name in requires:
                result.append(mod_name)
        return sorted(result)

    def _seed_modules(self, name):
        if name in self._mods:
            return {name}
        seeds = set()
        for mod_name, (provides, requires) in self._mods.items():
            if name in provides:
                seeds.add(mod_name)
        return seeds

    def _depends_on(self, mod_a, mod_b):
        if mod_a not in self._mods or mod_b not in self._mods:
            return False
        provides_b = self._mods[mod_b][0]
        requires_a = self._mods[mod_a][1]
        if requires_a & provides_b:
            return True
        if mod_b in requires_a:
            return True
        return False

    def _reverse_closure_set(self, name):
        seeds = self._seed_modules(name)
        if not seeds:
            return set()
        removed = set(seeds)
        frontier = set(seeds)
        while frontier:
            new_frontier = set()
            for mod_name in self._mods:
                if mod_name in removed:
                    continue
                for f in frontier:
                    if self._depends_on(mod_name, f):
                        new_frontier.add(mod_name)
                        break
            removed |= new_frontier
            frontier = new_frontier
        return removed

    def invalidate(self, name):
        removed = self._reverse_closure_set(name)
        for mod_name in removed:
            del self._mods[mod_name]
        return removed

    def reverse_closure(self, name):
        return self._reverse_closure_set(name)

    def missing(self):
        all_provided = set()
        for mod_name, (provides, requires) in self._mods.items():
            all_provided |= provides
        all_required = set()
        for mod_name, (provides, requires) in self._mods.items():
            all_required |= requires
        return all_required - all_provided

    def cycles(self):
        adj = {name: set() for name in self._mods}
        for a in self._mods:
            for b in self._mods:
                if a != b and self._depends_on(a, b):
                    adj[a].add(b)

        cycles = set()

        def dfs(start, current, path, visited):
            for neighbor in adj[current]:
                if neighbor == start:
                    cycles.add(tuple(sorted(path)))
                elif neighbor > start and neighbor not in visited:
                    dfs(start, neighbor, path + [neighbor], visited | {neighbor})

        for node in sorted(self._mods):
            dfs(node, node, [node], {node})

        return sorted(cycles)

    def to_json(self):
        result = {}
        for name in sorted(self._mods):
            provides, requires = self._mods[name]
            result[name] = {
                'provides': sorted(provides),
                'requires': sorted(requires),
            }
        return result
