        region = None
        if src in self._parallel:
            region = src
        else:
            region = self._find_region_for_state(src)

        # Entering (or re-entering) a branch of the active region
        if region is not None:
            branches = self._get_parallel_branches(region)
            if target in branches:
                self._parallel[region][target] = target
                self.state = target
                self._history.append(target)
                if self._on_transition:
