            except Exception:
                # Roll back
                self.state = src
                self._history.pop()
                if self._is_parallel(target):
                    del self._parallel[target]
                if region is not None:
                    for branch, current in self._parallel[region].items():
                        if current == target:
                            self._parallel[region][branch] = src
                            break
                raise
